<!-- prettier-ignore -->
<dialog class="{{ $classes }}" id="{{ $id }}-command-palette" aria-labelledby="{{ $id }}-title" data-cm-controller="command-palette" data-cm-command-palette-state="{{ $open ? 'open' : 'closed' }}"@if ($open) open@endif{!! $attributes !!}><div class="cm-command-palette__surface"><header class="cm-command-palette__header"><h2 class="cm-command-palette__title" id="{{ $id }}-title">{{ $title }}</h2><button class="cm-command-palette__close" type="button" aria-label="{{ $closeLabel }}" data-cm-command-palette-close>×</button></header><input class="cm-command-palette__input" type="search" role="combobox" aria-autocomplete="list" aria-expanded="{{ $open ? 'true' : 'false' }}" aria-controls="{{ $id }}-listbox"@if ($activeId !== null) aria-activedescendant="{{ $id }}-option-{{ $activeId }}"@endif placeholder="{{ $placeholder }}" value="{{ $query }}" data-cm-command-palette-input autofocus><ul class="cm-command-palette__list" id="{{ $id }}-listbox" role="listbox">@foreach ($commands as $command)<li class="cm-command-palette__option@if ($command['active']) cm-command-palette__option--active@endif" id="{{ $id }}-option-{{ $command['id'] }}" role="option" aria-selected="{{ $command['active'] ? 'true' : 'false' }}"@if ($command['disabled']) aria-disabled="true"@endif data-cm-command-palette-option data-cm-command-value="{{ $command['id'] }}"@if ($command['keywords'] !== null) data-cm-command-keywords="{{ $command['keywords'] }}"@endif@if (!$command['visible']) hidden@endif>{{ $command['label'] }}</li>@endforeach</ul><p class="cm-command-palette__empty"@if (!$empty) hidden@endif>{{ $emptyText }}</p></div></dialog>
